// This module belongs exclusively to Next.js server code and must never be imported in browser components.
// Reuse the Prisma 7 client generated by prisma-client-js in your repository.
import { PrismaClient } from "@prisma/client";
// Prisma 7 requires an explicit PostgreSQL driver adapter.
import { PrismaPg } from "@prisma/adapter-pg";

// Avoid accidentally initializing the adapter with an empty connection string.
const url = process.env.DATABASE_URL;
// A missing URL should fail early and descriptively.
if (!url) throw new Error("DATABASE_URL_MISSING");

// Retain one instance across hot reloads in local development.
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

// Construct a PostgreSQL connection adapter with a small pool for this VPS-sized app.
const adapter = new PrismaPg({ connectionString: url, max: 5 });

// Reuse an existing instance if Next.js hot-reloaded this module.
export const prisma = globalForPrisma.prisma ?? new PrismaClient({ adapter });

// Cache only during development; production normally has a single module instance.
if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;
